(function(){'use strict';
if(!window.DesktopApp?.marketScanner||!window.PriceBook)return;
const api=window.DesktopApp.marketScanner,book=window.PriceBook,original=book.resolve.bind(book);let rows=[],rowSignature='',index=new Map();
book.resolve=function(server,id,city,q,action,quote={},timestamp){const saved=book.get(server,id,city,q,action);if(saved?.source==='manual')return original(server,id,city,q,action,quote,timestamp);const row=index.get([server,id,city,Number(q)].join('|')),side=action==='bid'?'bid':'ask',time=row?.[side+'Time'];if(row?.[side]>0&&Date.now()-time<7200000&&time<=Date.now()+60000)return {...quote,price:row[side],age:Math.max(0,(Date.now()-time)/3600000),timestamp:new Date(time).toISOString(),reason:'',sourceLabel:'Считано с рынка · '+new Date(time).toLocaleTimeString('ru-RU'),fromScanner:true};return original(server,id,city,q,action,quote,timestamp);};
const panel=document.createElement('dialog');panel.className='market-scanner';panel.style.cssText='padding:24px;border:1px solid #667368;border-radius:8px;max-width:650px;background:var(--panel,#f8efd8);color:var(--ink,#332d20)';panel.innerHTML='<h3>Сканирование рынка</h3><button type="button" class="button" data-close>Закрыть</button><p>Просматривайте товары в игре — полученные цены поступят в расчёты. Выберите сервер игры перед включением. Цены действуют 2 часа, ручные цены сохраняют приоритет.</p><label>Сервер игры <select><option value="europe">Европа</option><option value="west">Америка</option><option value="east">Азия</option></select></label> <button type="button" class="button" data-toggle>Включить сканер рынка</button><p role="status" aria-live="polite"></p><p data-cities></p><p>Движок встроен в Albion Lab и работает в фоне. Для захвата нужен установленный Npcap. Цены передаются только в это приложение. Сервер сканирования задаётся здесь независимо от сервера открытого расчёта.</p>';
document.body.append(panel);panel.querySelector('[data-close]').onclick=()=>panel.close();const opener=document.createElement('button');opener.type='button';opener.className='button';opener.textContent='Сканер рынка';opener.onclick=()=>{panel.showModal();};document.querySelector('.header-actions')?.append(opener);const status=panel.querySelector('[role=status]'),toggle=panel.querySelector('[data-toggle]'),select=panel.querySelector('select');let running=false;
function paint(state){rows=state.quotes||[];running=state.running;const signature=JSON.stringify(rows),changed=signature!==rowSignature;rowSignature=signature;if(changed)index=new Map(rows.map(r=>[[r.server,r.item,r.city,r.quality].join('|'),r]));opener.textContent=running?'Сканер рынка · включён':'Сканер рынка';const counts={};for(const row of rows)if(row.server===select.value)counts[row.city]=(counts[row.city]||0)+1;panel.querySelector('[data-cities]').textContent=Object.entries(counts).map(([city,count])=>city+': '+count).join(' · ');select.disabled=running;toggle.textContent=running?'Выключить сканер рынка':'Включить сканер рынка';status.textContent=(state.configured?'Встроенный сканер готов. ':'Движок отсутствует. Переустановите Albion Lab. ')+(state.message||'')+' · Сохранено ордеров: '+state.orders;if(changed)document.dispatchEvent(new Event('pricebookchange'));}
async function action(name,arg){toggle.disabled=true;try{paint(await api.action(name,arg));}catch(e){status.textContent=e.message;}finally{toggle.disabled=false;}}
toggle.onclick=()=>action(running?'stop':'start',select.value);api.onChanged(paint);action('state');setInterval(()=>api.action('state').then(paint).catch(()=>{}),60000);
})();
